frappe.ui.form.on("Dental Test", {
  refresh(frm) {
    var list = document.getElementsByClassName("tooth");
    list.forEach((element) => {

      element.addEventListener("click", (e) => {
        let selected_tooth = e.target.id;
        cur_frm.set_value("selected_tooth", selected_tooth);
        cur_frm.refresh_field("selected_tooth");
      });
    });
  },
  selected_tooth(frm){
    var list = document.getElementsByClassName("tooth"); 
    list.forEach((element) => {

      const className = element.className
      if(className == "tooth active"){
        element.classList.remove('active');
        element.removeAttribute("style")
      }
      let selected_tooth = element.id;
      if(cur_frm.doc.selected_tooth==selected_tooth){
        element.classList.add("active");  
        element.setAttribute('style', 'border: 3px solid #2490EF;')
      }
      console.log(cur_frm.doc.selected_tooth == selected_tooth)

    })
  }
});

