frappe.ui.form.on("Sales Invoice", {
  apply_on_invoice: async function (frm) {
    console.log(
      "{{{{{{{{{{{{{{{{{{{{{{{{{{{{{{{ Start Code }}}}}}}}}}}}}}}}}}}}}}}}}}}}}}}}}"
    );

    // Insurance Items
    // Item / Insured by / Price / Insured amount /copay / Bal

    let insurance_items = [];

    // All Invoiced Items  []
    let invoiced_items = cur_frm.doc.items;

    // Current Primary Insurance
    let insurance_category = frm.doc.default_insurance;

    // Current Invoice Type e.g. Inpatient / Outpatient
    let invoice_type = "Outpatient";

    if (!invoiced_items || !insurance_category || !invoice_type) return;

    // Get All Billing Rules
    const billing_rules_items = await get_insurance_billing_rules_items_table(
      insurance_category,
      invoice_type
    );

    let templates_for_billing_rules = [];

    let getBillingRulesTemplates = async (billing_rules_item) => {
      await frappe
        .call({
          method:
            "gch_custom.services.rest.get_insurance_billing_rule_template",
          args: {
            billing_rule_name:
              billing_rules_item.insurance_billing_rule_templates,
          },
        })
        .done((r) => {
          // console.log("result &&&&&&&&&&&&&&");
          // console.log(r.message);
          // console.log("result &&&&&&&&&&&&&&");
          console.log("template found");
          templates_for_billing_rules.push(r.message);
        });
    };

    billing_rules_items.forEach((billing_rules_item) => {
      ///////////////////////////////////////////////////////////
      getBillingRulesTemplates(billing_rules_item);
      //////////////////////////////////////////////////////////
    });

    // Get All PreAuths
    const preauth_items = await get_insurance_preauth_items_table(
      insurance_category,
      invoice_type
    );

    // Get All Copay
    const copay_items = await get_insurance_copay_items_table(
      insurance_category,
      invoice_type
    );

    // Get All Exclusions
    const excluded_items = await get_insurance_excluded_items_table(
      insurance_category,
      invoice_type
    );

    // calculate bal
    const cal_bal = (item_price, insured_amount) => {
      return item_price - insured_amount;
    };

    let items_for_billing_rules = [];

    let getBillingRulesItems = async (template) => {
      await frappe
        .call({
          method: "gch_custom.services.rest.get_billing_rule_template_items",
          args: {
            billing_rule_name: template.name,
          },
        })
        .done((r) => {
          console.log("result &&&&&&&&&&&&&&");
          console.log(template.apply_on);
          console.log(r.message);
          console.log("result &&&&&&&&&&&&&&");
          items_for_billing_rules = r.message;
        });
    };

    templates_for_billing_rules.forEach((template) => {
      console.log(template.apply_on === "Items");
      // getBillingRulesItems(template)

      if (template.apply_on === "Items") {
        ///////////////////////////////////////////////////////////
        frappe
          .call({
            method: "gch_custom.services.rest.get_billing_rule_template_items",
            args: {
              billing_rule_name: template.name,
            },
          })
          .done((r) => {
            console.log("result &&&&&&&&&&&&&&");
            console.log(template.apply_on);
            console.log(r.message);
            console.log("result &&&&&&&&&&&&&&");
            items_for_billing_rules = r.message;

            invoiced_items.forEach((invoiced_item) => {
              const {
                item_code: current_item_name,
                item_group: current_item_group,
                amount: current_item_amount,
              } = invoiced_item;

              const billing_rule_template_item_exists =
                items_for_billing_rules.find(
                  (item) => item.item_code == current_item_name
                );

              if (billing_rule_template_item_exists) {
                // Check rate type i.e Discount Percentage / Flat Rate / Discount Amount / Max Amount
                if (template.rate_type == "Discount Percentage") {
                  let insured_amount =
                    (current_item_amount * template.percentage_discount) / 100;

                  insurance_items.push({
                    insurance_category,
                    item: current_item_name,
                    item_group: current_item_group,
                    price: current_item_amount,
                    copay_amount: 0,
                    insured_amount,
                    bal: cal_bal(current_item_amount, insured_amount),
                  });
                }
                if (template.rate_type == "Flat Rate") {
                  let insured_amount =
                    current_item_amount < template.fixed_amount
                      ? current_item_amount
                      : template.fixed_amount;

                  insurance_items.push({
                    insurance_category,
                    item: current_item_name,
                    item_group: current_item_group,
                    price: current_item_amount,
                    copay_amount: 0,
                    insured_amount,
                    bal: cal_bal(current_item_amount, insured_amount),
                  });
                }
                if (template.rate_type == "Discount Amount") {
                  let insured_amount =
                    current_item_amount - template.discount_amount;

                  insurance_items.push({
                    insurance_category,
                    item: current_item_name,
                    item_group: current_item_group,
                    price: current_item_amount,
                    copay_amount: 0,
                    insured_amount,
                    bal: cal_bal(current_item_amount, insured_amount),
                  });
                }
                if (template.rate_type == "Max Amount") {
                  let insured_amount =
                    current_item_amount > template.maximum_amount
                      ? template.maximum_amount
                      : current_item_amount;

                  insurance_items.push({
                    insurance_category,
                    item: current_item_name,
                    item_group: current_item_group,
                    price: current_item_amount,
                    copay_amount: 0,
                    insured_amount,
                    bal: cal_bal(current_item_amount, insured_amount),
                  });
                }
              }
            });
            if (insurance_items.length > 0) {
              // set insurance items
              // Reset Table
              frm.doc.invoice_insurance_item_table = [];

              insurance_items.forEach((item) => {
                let entry = frm.add_child("invoice_insurance_item_table");

                entry.item = item.item;
                entry.insurance_category = item.insurance_category;
                entry.price = item.price;
                entry.copay_amount = item.copay_amount;
                entry.insured_amount = item.insured_amount;
                entry.bal = item.bal;
              });
              refresh_field("invoice_insurance_item_table");
            }
          });

        // getBillingRulesItems(template)
        //////////////////////////////////////////////////////////
      }
    });

    invoiced_items.forEach((invoiced_item) => {
      const {
        item_code: current_item_name,
        item_group: current_item_group,
        amount: current_item_amount,
      } = invoiced_item;
      // console.table({
      //   current_item_name,
      //   current_item_group,
      //   current_item_amount,
      // });

