    if (frm.doc.weight_in_kilograms <= 0) {
      validated = false;
      msgprint("Invalid Weight");
      frappe.model.set_value(frm.doctype, frm.docname, "bmi", "");
      frappe.model.set_value(frm.doctype, frm.docname, "bsa", "");
      frappe.model.set_value(frm.doctype,frm.docname,"nursing_notes","" );
    } else {
      if (frm.doc.height_in_centimeters && frm.doc.weight_in_kilograms) {
        calculate_bmi(frm);
        calculate_bsa(frm);

        // Get Patient Date of Birth
            if (frm.doc.patient) {
                frappe.call({
                    method: "frappe.client.get",
                    args: {
                        doctype: "Patient",
                        name: frm.doc.patient
                    },
                    callback: function (data) {
                        const z_patientdob = data.message.dob;
                        const z_patientage = calculate_age(z_patientdob);
                        const z_gender = frm.doc.patient_sex;

                        //Check Gender here..if not M or F! 
                        if((z_patientdob) && (z_patientage < 6935) && (z_gender == 'Female' || z_gender == 'Male')) {
                            getcalculate_zscore(z_patientdob, z_gender, frm.doc.weight_in_kilograms, frm.doc.height_in_centimeters);
                        }
                        else
                        {
                            if(z_gender != 'Female' && z_gender != 'Male') {
                            msgprint({
                                title: __('Warning'),
                                indicator: 'orange',
                                message: __('Z-score percentiles NOT calculated. Gender not Male or Female')
                            });
                            }           
                        }                        
                    },
                });
            };    
        }
    }
  },

