//Calulate Age in Days
let calculate_age = function (birthdate) {
  let ageMS = Date.parse(Date()) - Date.parse(birthdate);
  const day_cons = 86400000;
  let agedays = Math.trunc(ageMS / day_cons);

  return agedays;
};



